import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_upper_tri_mm_ext = None


def _load_upper_tri_mm_extension():
    global _upper_tri_mm_ext
    if _upper_tri_mm_ext is None:
        cpp_source = r"""
#include <torch/extension.h>

torch::Tensor upper_tri_mm(torch::Tensor A, torch::Tensor B);
"""

        cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

namespace {

constexpr int TILE = 32;
__global__ void upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N
) {
    const int tile_row = blockIdx.y;
    const int tile_col = blockIdx.x;
    if (tile_col < tile_row) {
        return;
    }
    constexpr int WARPS_PER_BLOCK = 4;
    const int warp_id = threadIdx.y;
    const int lane = threadIdx.x;
    __shared__ float As[TILE][TILE + 1];
    __shared__ float Bs[TILE][TILE + 1];
    float acc[2][4] = {};
    const int warp_row = (warp_id >> 1) * 16;
    const int warp_col = (warp_id & 1) * 16;
    const int row_base = tile_row * TILE + warp_row + (lane >> 2) * 2;
    const int col_base = tile_col * TILE + warp_col + (lane & 3) * 4;
    const int first_k_tile = tile_row;
    const int last_k_tile = tile_col;
    for (int k_tile = first_k_tile; k_tile <= last_k_tile; ++k_tile) {
        const int k_base = k_tile * TILE;
        const int tid = warp_id * 32 + lane;
        for (int idx = tid; idx < TILE * TILE; idx += WARPS_PER_BLOCK * 32) {
            const int local_row = idx / TILE;
            const int local_col = idx - local_row * TILE;
            const int a_row = tile_row * TILE + local_row;
            const int a_col = k_base + local_col;
            As[local_row][local_col] =
                (a_row < N && a_col < N && a_col >= a_row)
                    ? A[a_row * N + a_col]
                    : 0.0f;
            const int b_row = k_base + local_row;
            const int b_col = tile_col * TILE + local_col;
            Bs[local_row][local_col] =
                (b_row < N && b_col < N && b_col >= b_row)
                    ? B[b_row * N + b_col]
                    : 0.0f;
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a[2];
            float b[4];
            #pragma unroll
            for (int i = 0; i < 2; ++i) {
                a[i] = As[warp_row + (lane >> 2) * 2 + i][k];
            }
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                b[j] = Bs[k][warp_col + (lane & 3) * 4 + j];
            }
            #pragma unroll
            for (int i = 0; i < 2; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    acc[i][j] = fmaf(a[i], b[j], acc[i][j]);
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        const int row = row_base + i;
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            const int col = col_base + j;
            if (row < N && col < N && row <= col) {
                C[row * N + col] = acc[i][j];
            }
        }
    }
}

} // namespace

torch::Tensor upper_tri_mm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.sizes() == B.sizes(), "A and B must have identical shapes");
    TORCH_CHECK(
        A.device() == B.device(),
        "A and B must be on the same CUDA device"
    );
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    const int N = static_cast<int>(A.size(0));
    at::cuda::CUDAGuard device_guard(A.device());

    auto C = torch::zeros({N, N}, A.options());

    if (N == 0) {
        return C;
    }

    const dim3 block(32, 4);
    const dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);

    upper_triangular_matmul_kernel<<<
        grid,
        block,
        0,
        at::cuda::getCurrentCUDAStream(A.device().index())
    >>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
